import React, { Component } from "react";
import "./Login.css";


export default class Login extends Component {
    constructor(props) {
        super(props);
        this.state = {
            activeTap:'signup',
            loginpage: null,

        };
    }

    componentDidMount() {
        const pageName = "LogIn";
        fetch(`http://localhost:3001/${pageName}`)
            .then(response => response.json())
            .then(page => {
                this.setState({ loginpage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }
    setActiveTap=(tab)=>{
        this.setState({activeTap:tab})
    }
    render() {
        const { loginpage } = this.state;
        if (!loginpage) return <div>PAGE NOT FOUND</div>;
        const textLogin = loginpage.text;
        const buttonsdata = loginpage.buttons;

        return (
            <div className="content-container">
                <div className="formboxx">
                    <div className="button-boxx">
                        <div id="btn"></div>
                        {buttonsdata.map((value, index) => (
                            <button
                                key={index}
                                type={value.type}
                                className={ value.className}
                            >
                                {value.text}
                            </button>
                        ))}
                    </div>

                    <div className="social-icons">
                        <img src={loginpage.Img2} alt="social icon 1" />
                        <img src={loginpage.Img1} alt="social icon 2" />
                    </div>

                    <form className="input-groupp">
                        {textLogin.map((item, index) => (
                            <input
                                key={index}
                                type={item.type}
                                className={item.className}
                                placeholder={item.placeholder}
                                required
                            />
                        ))}
                        <a href="#" className="forget">Forget/Change your password?</a>
                        <button type="submit" className="submit-btnn">Log in</button>
                    </form>
                </div>
            </div>
        );
    }
}
